from scipy.optimize import curve_fit
import warnings; warnings.filterwarnings('ignore')
gs={'T':lambda T:T,'invT':lambda T:1/T,'sqrtT':lambda T:np.sqrt(T),'logT':lambda T:np.log(T),'T2':lambda T:T**2,'expT':lambda T:np.exp(-T)}
res={}
for name,g in gs.items():
    def f(X,a,b,c,d,e,f_,h):
        e_,T_=X; G=g(T_)
        return a+b*G+(c+d*G)*(1-np.exp(-(e+f_*G)*e_))+h*e_
    best=None
    for s in range(4):
        p0=np.random.RandomState(s).randn(7)*2+np.array([0,3,6,-2,2,0,0.5])
        try:
            p,_=curve_fit(f,(eps,T),sigma,p0=p0,maxfev=40000)
            rr=np.mean((sigma-f((eps,T),*p))**2)/np.var(sigma)
            if best is None or rr<best[0]: best=(rr,p)
        except Exception: pass
    print(name, best[0] if best else None, np.round(best[1],3) if best else None)

from scipy.optimize import curve_fit
import warnings; warnings.filterwarnings('ignore')
X=(eps,T)
M={
'M1':(lambda X,a,b,c,k,m,g,h: a+b*X[1]+c*(1-np.exp(-k*X[0]*X[1]**m))+g*X[0]+h*X[0]*X[1],[1,4,10,1,0,0,0]),
'M2':(lambda X,a,b,c,k,n,g,h: a+b*X[1]+(c+h*X[1])*(1-np.exp(-k*X[0]))+g*X[0]**n,[1,4,10,1,1,0,0]),
'M3':(lambda X,a,b,c,d,n,m: a+b*X[1]+(c+d*X[1])*X[0]**(n+m*X[1]),[1,4,5,0,0.5,0]),
'M4':(lambda X,a,b,c,d,k,n,p: a+b*X[1]+(c+d*X[1])*(1-np.exp(-k*X[0]**n))+p*X[0],[1,4,10,-2,1,1,0.5]),
'M5':(lambda X,a,b,c,d,k,n,p,q: a+b*X[1]+(c+d*X[1])*(1-np.exp(-(k+q*X[1])*X[0]))+p*X[0]**n*X[1],[1,4,10,-2,1,1,0.5,0]),
}
for k,(f,p0) in M.items():
    best=None
    for s in range(5):
        pp=np.array(p0,float)+np.random.RandomState(s).randn(len(p0))*0.5*(s>0)
        try:
            p,_=curve_fit(f,X,sigma,p0=pp,maxfev=60000)
            rr=np.mean((sigma-f(X,*p))**2)/np.var(sigma)
            if best is None or rr<best[0]: best=(rr,p)
        except Exception: pass
    if best: print(k,best[0],np.round(best[1],4))
    else: print(k,'fail')
